int get_socket_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer) {
    if (!sock || !addr || !addr_len) {
        return -EBADFD;
    }

    struct sock *sk = sock->sk;
    if (!sk) {
        return -EBADFD;
    }

    lock_sock(sk);

    struct sockaddr_hci *hci_addr = (struct sockaddr_hci *)addr;
    hci_addr->hci_family = AF_BLUETOOTH;
    hci_addr->hci_dev = sk->sk_hci_dev;
    hci_addr->hci_channel = sk->sk_hci_channel;

    *addr_len = sizeof(struct sockaddr_hci);
    release_sock(sk);

    return 0;
}

int get_bt_sock_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer) {
    if (!sock || !addr || !addr_len) {
        return -EBADFD;
    }

    struct sock *sk = sock->sk;
    if (!sk || sk->sk_type != SOCK_RAW || sk->sk_protocol != BTPROTO_HCI) {
        return -EBADFD;
    }

    lock_sock(sk);
    struct sockaddr_hci *hci_addr = (struct sockaddr_hci *)addr;
    hci_addr->hci_family = AF_BLUETOOTH;
    hci_addr->hci_dev = sk->sk_bound_dev_if;
    hci_addr->hci_channel = sk->sk_priority;
    release_sock(sk);

    *addr_len = sizeof(struct sockaddr_hci);
    return 0;
}

int get_bt_sock_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer) {
    struct sockaddr_hci *haddr = (struct sockaddr_hci *)addr;

    if (!sock || !addr || !addr_len)
        return -EBADFD;

    if (peer) {
        if (!hci_conn_get_info(sock, haddr))
            return -EBADFD;
    } else {
        if (!hci_dev_get_info(sock, haddr))
            return -EBADFD;
    }

    haddr->hci_family = AF_BLUETOOTH;
    *addr_len = sizeof(struct sockaddr_hci);
    return 0;
}

int get_bluetooth_socket_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer)
{
    struct sockaddr_hci *hci_addr = (struct sockaddr_hci *)addr;

    if (!sock || !sock->sk || !sock->sk->sk_prot || !sock->sk->sk_prot->obj_size)
        return -EBADFD;

    sock_lock_sock(sock);

    hci_addr->hci_family = AF_BLUETOOTH;
    hci_addr->hci_dev = sock->sk->sk_dev_id;
    hci_addr->hci_channel = sock->sk->sk_type;

    sock_unlock_sock(sock);

    *addr_len = sizeof(struct sockaddr_hci);
    return 0;
}
